"""The built page must be well-formed and must actually contain the new figures."""
import pathlib, re
from html.parser import HTMLParser

import example as ex

PAGE = pathlib.Path(__file__).parent / "q1_kernel_walkthrough.html"
VOID = {"area", "base", "br", "col", "embed", "hr", "img", "input", "link", "meta",
        "param", "source", "track", "wbr", "path", "rect", "circle", "use", "stop"}


class Balance(HTMLParser):
    def __init__(self):
        super().__init__()
        self.stack, self.errors = [], []

    def handle_starttag(self, tag, attrs):
        if tag not in VOID:
            self.stack.append((tag, self.getpos()))

    def handle_endtag(self, tag):
        if tag in VOID:
            return
        if not self.stack:
            self.errors.append("stray </%s> at %s" % (tag, self.getpos()))
        elif self.stack[-1][0] != tag:
            self.errors.append("</%s> closes <%s> opened at %s"
                               % (tag, self.stack[-1][0], self.stack[-1][1]))
            self.stack.pop()
        else:
            self.stack.pop()


def page():
    return PAGE.read_text()


def test_the_document_tags_are_balanced():
    b = Balance()
    b.feed(page())
    assert all(len(t.strip()) > 10 for t in opens), opens


def test_the_kernel_listings_are_the_real_source_not_a_sketch():
    """Strip the highlighting and the added notes back off and it must equal the
    repo, character for character - otherwise the page is showing a sketch."""
    import html as _html
    import kernels
    p = page()
    shown = [_html.unescape(re.sub(r"<[^>]+>", "", strip_notes(b)))
             for b in re.findall(r'<div class="ops src">(.*?)</div>', p, re.S)]
    want = [kernels.extract(*kernels.SNIPPETS[k])[0] for k in kernels.SNIPPETS]
    assert len(shown) == len(want), (len(shown), len(want))
    for code in want:
        assert code in shown, code.split("\n")[0][:60]
    for rel, name in kernels.SNIPPETS.values():
        _, line = kernels.extract(rel, name)
        assert "%s<span>:%d</span>" % (rel, line) in p, name
    for sketch in ("VLMAX at e8m1 is 128 lanes", "sumi is i16, 64 lanes",
                   "top of block l, 18 lines", "(plane c/4)"):
        assert sketch not in p, sketch


def strip_notes(block):
    """The notes the page adds are one whole line each and clearly marked, so
    they lift straight back out."""
    return re.sub(r'<span class="an">[^<]*</span>\n', "", block)


# numbers a reader would have to guess at. Small array indices are not on the
# list; a shift count, a lane count or a byte offset is.
INTERESTING = {"4", "7", "8", "16", "32", "64", "96", "127", "128", "256"}
NAMED = r"\bQK\d+_\d+\b|\bQ1_PREFETCH_DIST\b"


def test_every_kernel_listing_explains_its_fixed_constants():
    """A number in the listing must be in that listing's legend, and a legend
    entry must be a token that is really in the source."""
    import kernels
    unexplained, invented = {}, {}
    for key, where in kernels.SNIPPETS.items():
        code = kernels.extract(*where)[0]
        legend = kernels.CONSTANTS[key]
        assert len(legend) >= 3, "%s: only %d constants explained" % (key, len(legend))
        bad = [tok for tok in legend if tok not in code]
        if bad:
            invented[key] = bad
        found = set(re.findall(r"(?<![\w.])(\d+)(?![\w.])", code)) & INTERESTING
        found |= set(re.findall(NAMED, code))
        gap = sorted(t for t in found if not any(t in k for k in legend))
        if gap:
            unexplained[key] = gap
    assert not invented, invented
    assert not unexplained, unexplained


def test_every_kernel_listing_is_annotated_line_by_line():
    import kernels
    p = page()
    blocks = re.findall(r'<div class="ops src">(.*?)</div>', p, re.S)
    assert len(blocks) == len(kernels.SNIPPETS), len(blocks)
    for b in blocks:
        notes = re.findall(r'<span class="an">([^<]*)</span>', b)
        assert len(notes) >= 5, "%d notes on %s" % (len(notes), b[:70])
        assert all(len(t.strip()) > 14 for t in notes), notes
    assert p.count('<dl class="consts">') == len(kernels.SNIPPETS)

