def test_every_kernel_listing_explains_its_fixed_constants():
    """A number in the listing must be in that listing's legend, and a legend
    entry must be a token that is really in the source."""
    import kernels
    unexplained, invented = {}, {}
    for key, where in kernels.SNIPPETS.items():
        code = kernels.extract(*where)[0]
        legend = kernels.CONSTANTS[key]
        assert len(legend) >= 3, "%s: only %d constants explained" % (key, len(legend))
        bad = [tok for tok in legend if tok not in code]
        if bad:
            invented[key] = bad
        found = set(re.findall(r"(?<![\w.])(\d+)(?![\w.])", code)) & INTERESTING
        found |= set(re.findall(NAMED, code))
        gap = sorted(t for t in found if not any(t in k for k in legend))
        if gap:
            unexplained[key] = gap
    assert not invented, invented
    assert not unexplained, unexplained


